insert into template_versions (id, template_id, version, status, definition, change_note, published_at) values ('tpl-cm-v1', 'tpl-cm', 1, 'published', '{"sections":[{"id":"cm-habits","title":"Com he treballat","emoji":"🎒","intro":"Pensa en aquestes setmanes a l’escola i tria la resposta que més s’assembla al que has fet.","questions":[{"id":"cm-h1","type":"scale","text":"He intentat acabar les feines.","scaleId":"cm3","required":true,"active":true},{"id":"cm-h2","type":"scale","text":"Quan no entenia una cosa, he preguntat o he buscat ajuda.","scaleId":"cm3","required":true,"active":true},{"id":"cm-h3","type":"scale","text":"He revisat una feina després de rebre un consell.","scaleId":"cm3","required":true,"active":true},{"id":"cm-h4","type":"scale","text":"He escoltat i he col·laborat amb els companys.","scaleId":"cm3","required":true,"active":true}]},{"id":"cm-arees","title":"Les meves àrees","emoji":"📚","intro":"Per a cada àrea, digues com treballes.","questions":[{"id":"cm-arees-q","type":"subjects","text":"Com treballo a cada àrea","required":true,"active":true,"criteria":[{"id":"auto","label":"Autonomia","prompt":"Com ho faig?","scaleId":"auto3"}]}]},{"id":"cm-reflexio","title":"Penso i escric","emoji":"✏️","questions":[{"id":"cm-r1","type":"shortText","text":"Aquest trimestre he après a…","required":true,"maxLength":160,"active":true,"help":"Escriu una cosa que ara saps fer i abans no."},{"id":"cm-r2","type":"shortText","text":"El trimestre vinent vull practicar…","required":true,"maxLength":160,"active":true,"help":"Una cosa que vols fer millor."}]}]}', 'Versió inicial basada en el model en paper.', '2026-09-01T08:00:00Z');
insert into template_versions (id, template_id, version, status, definition, change_note, published_at) values ('tpl-cs-v1', 'tpl-cs', 1, 'published', '{"sections":[{"id":"cs-objectiu-anterior","title":"El meu objectiu anterior","emoji":"🎯","intro":"Recordes l’objectiu que et vas posar a l’última autoavaluació?","questions":[{"id":"cs-goal-review","type":"goalReview","text":"Com ha anat el meu objectiu?","scaleId":"goal3","sourceQuestionId":"cs-obj","required":true,"active":true}]},{"id":"cs-habits","title":"Com aprenc","emoji":"🧭","intro":"Llegeix cada frase i tria amb quina freqüència ho has fet.","questions":[{"id":"cs-h1","type":"scale","text":"He acabat les feines a temps i amb cura.","scaleId":"freq4","required":true,"active":true},{"id":"cs-h2","type":"scale","text":"Quan alguna cosa m’ha costat, he buscat una manera de resoldre-la.","scaleId":"freq4","required":true,"active":true},{"id":"cs-h3","type":"scale","text":"He fet servir els consells del mestre o la mestra per millorar.","scaleId":"freq4","required":true,"active":true},{"id":"cs-h4","type":"scale","text":"He participat a classe i he compartit les meves idees.","scaleId":"freq4","required":true,"active":true},{"id":"cs-h5","type":"scale","text":"He treballat bé en equip i he respectat els companys.","scaleId":"freq4","required":true,"active":true}]},{"id":"cs-arees","title":"Les meves àrees","emoji":"📚","intro":"Valora cada àrea: què n’has après i com hi treballes.","questions":[{"id":"cs-arees-q","type":"subjects","text":"Valoració de les àrees","required":true,"active":true,"criteria":[{"id":"dom","label":"Domini","prompt":"Què n’he après?","scaleId":"dom4"},{"id":"auto","label":"Autonomia","prompt":"Com hi treballo?","scaleId":"auto3"}]}]},{"id":"cs-reflexio","title":"Reflexiono","emoji":"💭","questions":[{"id":"cs-evid","type":"shortText","text":"Una feina de la qual estic orgullós o orgullosa, i per què","required":true,"maxLength":220,"active":true,"pdfLabel":"Una feina de la qual estic orgullós/osa"},{"id":"cs-dif","type":"longText","text":"Una dificultat que he tingut i com l’he afrontada","required":true,"maxLength":300,"active":true,"pdfLabel":"Una dificultat i com l’he afrontada"},{"id":"cs-obj","type":"shortText","text":"El meu objectiu per al trimestre vinent","required":true,"maxLength":200,"active":true,"help":"Ha de ser concret: què faràs i quan ho faràs."}]}]}', 'Versió inicial basada en el model en paper.', '2026-09-01T08:00:00Z');
insert into template_versions (id, template_id, version, status, definition, change_note, published_at) values ('tpl-eso-v1', 'tpl-eso', 1, 'published', '{"sections":[{"id":"eso-temps","title":"Temps, preparació i constància","emoji":"⏱️","intro":"Respon amb sinceritat. No és una nota: és una manera de conèixer-te millor.","questions":[{"id":"eso-t1","type":"scale","text":"Porto el material necessari a classe.","scaleId":"freq4na","required":true,"active":true},{"id":"eso-t2","type":"scale","text":"Faig els deures i les tasques dins del termini.","scaleId":"freq4na","required":true,"active":true},{"id":"eso-t3","type":"scale","text":"Planifico el temps d’estudi abans de les proves.","scaleId":"freq4na","required":true,"active":true},{"id":"eso-t4","type":"scale","text":"Reviso les feines abans de lliurar-les.","scaleId":"freq4na","required":true,"active":true},{"id":"eso-t5","type":"scale","text":"Mantinc l’esforç encara que una tasca em costi.","scaleId":"freq4na","required":true,"active":true}]},{"id":"eso-aprendre","title":"Participació i manera d’aprendre","emoji":"💡","questions":[{"id":"eso-p1","type":"scale","text":"Estic atent o atenta i participo a classe.","scaleId":"freq4na","required":true,"active":true},{"id":"eso-p2","type":"scale","text":"Pregunto quan tinc un dubte.","scaleId":"freq4na","required":true,"active":true},{"id":"eso-p3","type":"scale","text":"Aprofito les correccions per millorar.","scaleId":"freq4na","required":true,"active":true},{"id":"eso-p4","type":"scale","text":"Busco informació i recursos pel meu compte.","scaleId":"freq4na","required":true,"active":true},{"id":"eso-p5","type":"scale","text":"Faig servir esquemes, resums o altres estratègies d’estudi.","scaleId":"freq4na","required":true,"active":true}]},{"id":"eso-altres","title":"Treball amb els altres i compromís","emoji":"🤝","questions":[{"id":"eso-w1","type":"scale","text":"Col·laboro i faig la meva part en els treballs en grup.","scaleId":"freq4na","required":true,"active":true},{"id":"eso-w2","type":"scale","text":"Respecto les opinions i el torn de paraula dels altres.","scaleId":"freq4na","required":true,"active":true},{"id":"eso-w3","type":"scale","text":"Faig un ús responsable del mòbil i de l’ordinador.","scaleId":"freq4na","required":true,"active":true},{"id":"eso-w4","type":"scale","text":"Compleixo els compromisos que prenc.","scaleId":"freq4na","required":true,"active":true}]},{"id":"eso-materies","title":"Les meves matèries","emoji":"📚","intro":"Per a cada matèria: el resultat que preveus, l’esforç que hi has fet i com entens el que heu treballat.","questions":[{"id":"eso-mat-q","type":"subjects","text":"Valoració de les matèries","required":true,"active":true,"criteria":[{"id":"res","label":"Resultat que preveig","prompt":"Quin resultat preveig?","scaleId":"result4"},{"id":"esf","label":"Esforç que he fet","prompt":"Quin esforç hi he fet?","scaleId":"effort4"},{"id":"com","label":"Comprensió","prompt":"Entenc el que hem fet?","scaleId":"underst4"}],"subjectComment":{"prompt":"Què puc fer o què em cal?","required":false,"maxLength":300}}]},{"id":"eso-compromis","title":"El meu compromís","emoji":"🚀","questions":[{"id":"eso-accio","type":"longText","text":"La meva acció prioritària de millora","required":true,"maxLength":400,"active":true,"help":"Tria una sola cosa concreta que començaràs a fer a partir de demà."}]}]}', 'Versió inicial basada en el model en paper.', '2026-09-01T08:00:00Z');
